INSERT INTO [dbo].[san_pham] ([ma_san_pham], [ma_san_pham_code], [ma_danh_muc], [ten_san_pham], [slug], [mo_ta], [mo_ta_ai], [gia_trung_binh], [url_anh_dai_dien], [trang_thai], [ngay_tao], [ngay_cap_nhat], [ngay_xoa]) VALUES (19, N'SP0019', 1, N'test3', N'test3-1782785683204', N'không có j', NULL, 3000.00, N'/api/files/c991804e-7780-4895-be92-2c91bd46ba98.png', 1, '2026-06-30 09:14:43.4323685', '2026-07-13 14:14:57.9730527', '2026-07-13 14:14:57.9725386');
INSERT INTO [dbo].[san_pham] ([ma_san_pham], [ma_san_pham_code], [ma_danh_muc], [ten_san_pham], [slug], [mo_ta], [mo_ta_ai], [gia_trung_binh], [url_anh_dai_dien], [trang_thai], [ngay_tao], [ngay_cap_nhat], [ngay_xoa]) VALUES (20, N'SP0020', 1, N'576fhfgh', N'576fhfgh-1783897008787', N'Áo Polo Nike 576fhfgh mang đến phong cách trẻ trung và năng động, hoàn hảo cho những buổi dạo phố hay hoạt động thể thao. Được làm từ chất liệu vải cotton cao cấp, áo không chỉ nhẹ nhàng và thoáng khí mà còn mang lại sự thoải mái tuyệt đối cho người mặc. Thiết kế đơn giản nhưng tinh tế với logo Nike nổi bật, tạo điểm nhấn thời thượng cho trang phục hàng ngày.', NULL, 2815284.00, N'/api/files/78e3c0cf-c86b-4c99-b33b-2561032053e7.png', 1, '2026-07-13 04:37:06.2078935', '2026-07-13 14:14:55.8231542', '2026-07-13 14:14:55.8139380');
INSERT INTO [dbo].[san_pham] ([ma_san_pham], [ma_san_pham_code], [ma_danh_muc], [ten_san_pham], [slug], [mo_ta], [mo_ta_ai], [gia_trung_binh], [url_anh_dai_dien], [trang_thai], [ngay_tao], [ngay_cap_nhat], [ngay_xoa]) VALUES (21, N'SP0021', 1, N'Áo Polo Xanh Đen Phối Cổ Thêu', N'o-polo-xanh-en-ph-i-c-th-u-1783920144078', N'', NULL, 210000.00, N'/api/files/b844291f-48cc-4aaf-9e34-0f11fc1cdea0.jpeg', 1, '2026-07-13 12:22:24.2650666', '2026-07-13 12:22:24.5092892', NULL);
INSERT INTO [dbo].[san_pham] ([ma_san_pham], [ma_san_pham_code], [ma_danh_muc], [ten_san_pham], [slug], [mo_ta], [mo_ta_ai], [gia_trung_binh], [url_anh_dai_dien], [trang_thai], [ngay_tao], [ngay_cap_nhat], [ngay_xoa]) VALUES (22, N'SP0022', 1, N'Áo Polo Nam', N'o-polo-nam-1783922287918', N'Áo Polo Nam Nike mang đến sự kết hợp hoàn hảo giữa phong cách thể thao năng động và sự thanh lịch. Được làm từ chất liệu vải cotton thấm hút mồ hôi, áo giúp bạn luôn cảm thấy thoải mái và dễ chịu trong mọi hoạt động. Thiết kế cổ điển với các chi tiết tinh tế, áo phù hợp để mặc trong các buổi tham gia thể thao hay dạo phố.', NULL, 370000.00, NULL, 1, '2026-07-13 12:58:08.1401417', '2026-07-13 12:58:08.6356412', NULL);
INSERT INTO [dbo].[san_pham] ([ma_san_pham], [ma_san_pham_code], [ma_danh_muc], [ten_san_pham], [slug], [mo_ta], [mo_ta_ai], [gia_trung_binh], [url_anh_dai_dien], [trang_thai], [ngay_tao], [ngay_cap_nhat], [ngay_xoa]) VALUES (23, N'SP0023', 1, N'Áo Polo thể thao', N'o-polo-th-thao-1783925305046', N'Áo Polo thể thao Beyono được thiết kế với phong cách năng động, phù hợp cho những buổi tập luyện hay dạo phố. Chất liệu vải thấm hút mồ hôi hiệu quả, mang lại cảm giác thoải mái và dễ chịu cho người mặc. Điểm nhấn là đường may tinh tế và màu sắc trẻ trung, giúp bạn luôn nổi bật và thời trang trong mọi hoạt động.', NULL, 199000.00, NULL, 1, '2026-07-13 13:48:25.3166539', '2026-07-13 13:48:25.6878572', NULL);
INSERT INTO [dbo].[san_pham] ([ma_san_pham], [ma_san_pham_code], [ma_danh_muc], [ten_san_pham], [slug], [mo_ta], [mo_ta_ai], [gia_trung_binh], [url_anh_dai_dien], [trang_thai], [ngay_tao], [ngay_cap_nhat], [ngay_xoa]) VALUES (24, N'SP0024', 9, N'test', N'test-1783930686686', N'Giày thể thao Nike "test" mang phong cách hiện đại, trẻ trung, phù hợp cho cả vận động và thời trang hàng ngày. Được làm từ chất liệu vải cao cấp và đế cao su bền bỉ, sản phẩm đảm bảo sự thoải mái và độ bám tốt trong từng bước đi. Thiết kế tối giản nhưng tinh tế giúp tôn lên cá tính năng động của người sử dụng.', NULL, 10000.00, NULL, 1, '2026-07-13 15:15:06.1178507', '2026-07-31 14:39:59.3189067', '2026-07-31 14:39:59.3088906');
INSERT INTO [dbo].[san_pham] ([ma_san_pham], [ma_san_pham_code], [ma_danh_muc], [ten_san_pham], [slug], [mo_ta], [mo_ta_ai], [gia_trung_binh], [url_anh_dai_dien], [trang_thai], [ngay_tao], [ngay_cap_nhat], [ngay_xoa]) VALUES (25, N'SP0025', 3, N'dewr', N'dewr-1785512124556', N'Quần dewr của thương hiệu Puma mang đến thiết kế thể thao năng động, phù hợp cho cả luyện tập và đời sống hàng ngày. Được chế tác từ chất liệu vải thun co giãn, quần này không chỉ giúp bạn thoải mái trong từng chuyển động mà còn tạo cảm giác mát mẻ, dễ chịu. Phong cách hiện đại với đường may tinh tế và logo Puma ở bên hông, quần dewr chắc chắn là lựa chọn lý tưởng cho những tín đồ yêu thích sự trẻ trung và thời trang.', NULL, 4069.00, N'/api/files/6cacc9f9-ab03-4c1e-a738-28bee4879ce5.jpg', 1, '2026-07-16 02:26:10.9096872', '2026-07-31 22:35:24.9717533', NULL);
