INSERT INTO [dbo].[tin_nhan_ai] ([ma_tin_nhan], [ma_hoi_thoai], [noi_dung], [nguoi_gui], [ngay_tao], [hinh_anh]) VALUES (11, 2, N'Hello! How are you today?', N'user', '2026-07-07 22:27:07.6490390', NULL);
INSERT INTO [dbo].[tin_nhan_ai] ([ma_tin_nhan], [ma_hoi_thoai], [noi_dung], [nguoi_gui], [ngay_tao], [hinh_anh]) VALUES (12, 2, N'Chào bạn! Mình rất vui được hỗ trợ bạn hôm nay. Bạn cần tư vấn gì về sản phẩm áo polo tại ZestStore không?', N'ai', '2026-07-07 22:27:11.0064885', NULL);
INSERT INTO [dbo].[tin_nhan_ai] ([ma_tin_nhan], [ma_hoi_thoai], [noi_dung], [nguoi_gui], [ngay_tao], [hinh_anh]) VALUES (13, 2, N'có áo size L không', N'user', '2026-07-07 22:27:37.9018140', NULL);
INSERT INTO [dbo].[tin_nhan_ai] ([ma_tin_nhan], [ma_hoi_thoai], [noi_dung], [nguoi_gui], [ngay_tao], [hinh_anh]) VALUES (14, 2, N'Xin lỗi, đã có lỗi xảy ra. Vui lòng thử lại sau.', N'ai', '2026-07-07 22:27:38.8185652', NULL);
INSERT INTO [dbo].[tin_nhan_ai] ([ma_tin_nhan], [ma_hoi_thoai], [noi_dung], [nguoi_gui], [ngay_tao], [hinh_anh]) VALUES (15, 2, N'có áo size L không', N'user', '2026-07-07 22:31:13.7021518', NULL);
INSERT INTO [dbo].[tin_nhan_ai] ([ma_tin_nhan], [ma_hoi_thoai], [noi_dung], [nguoi_gui], [ngay_tao], [hinh_anh]) VALUES (16, 2, N'Có, tại ZestStore chúng tôi có áo polo size L. Bạn có muốn biết thêm thông tin về màu sắc hoặc kiểu dáng cụ thể nào không? Hoặc nếu bạn cần hỗ trợ về đơn hàng, đừng ngần ngại hỏi nhé!', N'ai', '2026-07-07 22:31:15.9880361', NULL);
INSERT INTO [dbo].[tin_nhan_ai] ([ma_tin_nhan], [ma_hoi_thoai], [noi_dung], [nguoi_gui], [ngay_tao], [hinh_anh]) VALUES (17, 2, N'hàng bán chạy nhất còn hàng không', N'user', '2026-07-07 22:31:31.4309625', NULL);
INSERT INTO [dbo].[tin_nhan_ai] ([ma_tin_nhan], [ma_hoi_thoai], [noi_dung], [nguoi_gui], [ngay_tao], [hinh_anh]) VALUES (18, 2, N'Hiện tại, những mẫu áo polo bán chạy nhất ở ZestStore thường xuyên được cung cấp. Tuy nhiên, tình trạng hàng tồn kho có thể thay đổi nhanh chóng. Bạn có thể cho mình biết mẫu nào bạn đang quan tâm không? Mình sẽ kiểm tra và cung cấp thông tin chi tiết cho bạn!', N'ai', '2026-07-07 22:31:33.4897047', NULL);
INSERT INTO [dbo].[tin_nhan_ai] ([ma_tin_nhan], [ma_hoi_thoai], [noi_dung], [nguoi_gui], [ngay_tao], [hinh_anh]) VALUES (19, 2, N'bạn đề cử cho mình 1 số áo với', N'user', '2026-07-07 22:32:10.0479512', NULL);
INSERT INTO [dbo].[tin_nhan_ai] ([ma_tin_nhan], [ma_hoi_thoai], [noi_dung], [nguoi_gui], [ngay_tao], [hinh_anh]) VALUES (20, 2, N'Chắc chắn rồi! Dưới đây là một vài mẫu áo polo đang được ưa chuộng tại ZestStore:

1. **Áo Polo Cổ Bẻ Basic**: Với chất liệu cotton thoáng mát, kiểu dáng đơn giản, dễ phối đồ. Có nhiều màu sắc như xanh navy, xám, trắng.

2. **Áo Polo Phối Đường Kẻ**: Thiết kế trẻ trung và năng động, phù hợp cho cả đi làm và đi chơi. Có các màu sắc tươi sáng như đỏ, xanh lá.

3. **Áo Polo Thể Thao**: Được làm từ chất liệu thể thao cao cấp, thấm hút mồ hôi tốt, rất thích hợp cho những hoạt động ngoài trời. Màu sắc nổi bật như cam, vàng.

4. **Áo Polo Cổ Trụ**: Với thiết kế cổ cao, mang đến phong cách lịch lãm và sang trọng. Thường có các màu trung tính như đen, trắng, và xanh dương.

Bạn thấy mẫu nào phù hợp không? Mình cũng có thể giúp bạn chọn size phù hợp nếu bạn cho mình biết chiều cao và cân nặng của bạn nhé!', N'ai', '2026-07-07 22:32:15.2308464', NULL);
INSERT INTO [dbo].[tin_nhan_ai] ([ma_tin_nhan], [ma_hoi_thoai], [noi_dung], [nguoi_gui], [ngay_tao], [hinh_anh]) VALUES (21, 2, N'bây giờ mấy giờ rồi nhỉ', N'user', '2026-07-12 22:30:49.0123061', NULL);
INSERT INTO [dbo].[tin_nhan_ai] ([ma_tin_nhan], [ma_hoi_thoai], [noi_dung], [nguoi_gui], [ngay_tao], [hinh_anh]) VALUES (22, 2, N'Rất tiếc, mình không thể kiểm tra thời gian hiện tại. Nhưng bạn có thể xem trên điện thoại hoặc máy tính của mình để biết chính xác thời gian nhé! Nếu có bất cứ câu hỏi nào về sản phẩm hay đơn hàng, mình sẵn sàng hỗ trợ bạn!', N'ai', '2026-07-12 22:30:52.8182864', NULL);
INSERT INTO [dbo].[tin_nhan_ai] ([ma_tin_nhan], [ma_hoi_thoai], [noi_dung], [nguoi_gui], [ngay_tao], [hinh_anh]) VALUES (23, 2, N'áo nào mới ra gần đây', N'user', '2026-07-13 20:27:29.7267990', NULL);
INSERT INTO [dbo].[tin_nhan_ai] ([ma_tin_nhan], [ma_hoi_thoai], [noi_dung], [nguoi_gui], [ngay_tao], [hinh_anh]) VALUES (24, 2, N'Tại ZestStore, gần đây chúng tôi đã cho ra mắt một số mẫu áo polo mới rất đẹp và hiện đại. Dưới đây là một vài mẫu mới nhất:

1. **Áo Polo Minimalist**: Thiết kế đơn giản, tinh tế, phù hợp cho cả môi trường văn phòng và thời trang hàng ngày. Màu sắc hiện tại có trắng, đen và xanh nhạt.

2. **Áo Polo Họa Tiết Trẻ Trung**: Với họa tiết nổi bật trên nền màu sắc thời thượng, rất phù hợp cho những bạn trẻ năng động. Có nhiều biến thể màu sắc để lựa chọn.

3. **Áo Polo Chất Liệu Bamboo**: Sản phẩm thân thiện với môi trường, mềm mại và thoáng mát, sẽ là lựa chọn lý tưởng cho mùa hè. Màu sắc tự nhiên như be và xanh lá cây nhạt.

Nếu bạn muốn xem mẫu nào cụ thể hơn hoặc cần thêm thông tin về kích thước, màu sắc, hãy cho mình biết nhé!', N'ai', '2026-07-13 20:27:36.2739075', NULL);
INSERT INTO [dbo].[tin_nhan_ai] ([ma_tin_nhan], [ma_hoi_thoai], [noi_dung], [nguoi_gui], [ngay_tao], [hinh_anh]) VALUES (25, 2, N'áo này hợp với người vóc dáng như nào', N'user', '2026-07-13 20:28:45.5713677', N'data:image/jpeg;base64,');
INSERT INTO [dbo].[tin_nhan_ai] ([ma_tin_nhan], [ma_hoi_thoai], [noi_dung], [nguoi_gui], [ngay_tao], [hinh_anh]) VALUES (26, 2, N'Áo polo như trong hình này thường phù hợp với nhiều vóc dáng. Cụ thể:

1. **Vóc dáng mảnh mai**: Áo polo sẽ giúp tạo sự cân đối và có thể làm nổi bật xương quai xanh.

2. **Vóc dáng trung bình**: Kiểu dáng này có thể tôn lên đường nét cơ thể mà không làm bạn cảm thấy quá chật chội.

3. **Vóc dáng hơi đầy đặn**: Nếu bạn chọn size vừa vặn, áo sẽ giúp che khuyết điểm mà vẫn giữ được phong cách lịch sự và trẻ trung.

Màu sắc nhẹ nhàng và thiết kế tối giản cũng giúp dễ dàng kết hợp với nhiều trang phục khác. Bạn có thể phối với quần shorts hoặc quần jeans để tạo phong cách thoải mái nhưng vẫn thanh lịch. Nếu bạn cần thêm tư vấn về kích thước, đừng ngần ngại nhé!', N'ai', '2026-07-13 20:28:55.0626496', NULL);
INSERT INTO [dbo].[tin_nhan_ai] ([ma_tin_nhan], [ma_hoi_thoai], [noi_dung], [nguoi_gui], [ngay_tao], [hinh_anh]) VALUES (27, 2, N'tư vấn cho mình 1 kiểu áo cho nam 20 tuổi ', N'user', '2026-07-19 21:16:48.1466356', NULL);
INSERT INTO [dbo].[tin_nhan_ai] ([ma_tin_nhan], [ma_hoi_thoai], [noi_dung], [nguoi_gui], [ngay_tao], [hinh_anh]) VALUES (28, 2, N'Chắc chắn rồi! Dưới đây là một kiểu áo polo rất phù hợp cho nam 20 tuổi:

### **Áo Polo Họa Tiết Trẻ Trung**

- **Thiết kế**: Áo có họa tiết nhẹ nhàng, tươi sáng, mang lại cảm giác năng động và phong cách.
- **Chất liệu**: Cotton mềm mại, thoáng mát, thấm hút mồ hôi tốt, rất phù hợp cho mùa hè.
- **Màu sắc**: Có thể lựa chọn các màu sắc như xanh biển, đỏ tươi hoặc trắng có họa tiết nổi bật, giúp tạo điểm nhấn cho trang phục.
- **Phối đồ**: Có thể kết hợp với quần shorts hoặc quần jeans, cùng với sneaker hoặc giày thể thao để tạo nên phong cách trẻ trung và năng động.

Mẫu áo này không chỉ thoải mái mà còn giúp bạn dễ dàng thể hiện cá tính riêng, rất phù hợp với lứa tuổi 20. Nếu bạn cần thêm thông tin hoặc muốn biết về các mẫu cụ thể, hãy cho mình biết nhé!', N'ai', '2026-07-19 21:16:54.9663905', NULL);
INSERT INTO [dbo].[tin_nhan_ai] ([ma_tin_nhan], [ma_hoi_thoai], [noi_dung], [nguoi_gui], [ngay_tao], [hinh_anh]) VALUES (29, 2, N'hi', N'user', '2026-07-30 04:15:01.9828588', NULL);
INSERT INTO [dbo].[tin_nhan_ai] ([ma_tin_nhan], [ma_hoi_thoai], [noi_dung], [nguoi_gui], [ngay_tao], [hinh_anh]) VALUES (30, 2, N'Chào bạn! Bạn cần tư vấn gì về sản phẩm áo polo tại ZestStore không? Mình rất sẵn lòng giúp bạn!', N'ai', '2026-07-30 04:15:07.7892458', NULL);
